import json,sys,glob,os
runs=sys.argv[1:]
iv=[]
for r in runs:
  for f in glob.glob(r+'/agent-*.jsonl'):
    ts=[]
    for l in open(f,errors='replace'):
      try: t=json.loads(l).get('timestamp')
      except: continue
      if t: ts.append(t)
    if ts:
      meta=json.load(open(f.replace('.jsonl','.meta.json')))
      iv.append((min(ts),max(ts),r,os.path.basename(f)[6:12],meta.get('description') or meta.get('label') or ''))
ev=[]
for a,b,r,i,d in iv: ev.append((a,1)); ev.append((b,-1))
ev.sort()
cur=0;mx=0;at=None
for t,d in ev:
  cur+=d
  if cur>mx: mx=cur;at=t
print('agents',len(iv),'first',min(a for a,*_ in iv),'last',max(b for _,b,*_ in iv),'max concurrent',mx,'at',at)
# per-run concurrency
for r in runs:
  e=[]
  for a,b,rr,i,d in iv:
    if rr==r: e+= [(a,1),(b,-1)]
  e.sort();c=0;m=0
  for t,d in e:
    c+=d; m=max(m,c)
  print(r,sum(1 for x in iv if x[2]==r),'agents, max in run',m)
E
